CREATE TABLE users (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, business_name VARCHAR(255), business_slug VARCHAR(100) UNIQUE, theme VARCHAR(50) DEFAULT 'mustard', role VARCHAR(20) DEFAULT 'user', created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ingredients (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, stock INT DEFAULT 0, unit VARCHAR(20) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, description TEXT, price INT NOT NULL CHECK (price > 0), icon VARCHAR(100), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recipes (product_id INT REFERENCES products(id) ON DELETE CASCADE, ingredient_id INT REFERENCES ingredients(id) ON DELETE CASCADE, quantity INT NOT NULL CHECK (quantity > 0), PRIMARY KEY (product_id, ingredient_id));
CREATE TABLE orders (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id) ON DELETE CASCADE, customer_name VARCHAR(255) DEFAULT 'Cliente', total INT NOT NULL, status VARCHAR(50) DEFAULT 'pendiente', created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id SERIAL PRIMARY KEY, order_id INT REFERENCES orders(id) ON DELETE CASCADE, product_id INT REFERENCES products(id), product_name VARCHAR(255), quantity INT NOT NULL, price_at_sale INT NOT NULL);
